'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import styles from './Navbar.module.css';

const Navbar = () => {
    const pathname = usePathname();

    const navLinks = [
        { name: 'ГЛАВНАЯ', path: '/' },
        { name: 'ЦЕНЫ', path: '/pricing' },
        { name: 'ОБОРУДОВАНИЕ', path: '/tech' },
        { name: 'ПОРТФОЛИО', path: '/portfolio' },
        { name: 'КОНТАКТЫ', path: '/contacts' },
    ];

    return (
        <nav className={styles.navbar}>
            <Link href="/" className={styles.logo}>
                <span className={styles.logoP}>P</span>ULSE 3D
            </Link>

            <div className={styles.navLinks}>
                {navLinks.map((link) => (
                    <Link
                        key={link.path}
                        href={link.path}
                        className={`${styles.navLink} ${pathname === link.path ? styles.active : ''}`}
                    >
                        {link.name}
                    </Link>
                ))}
            </div>

            <div className={styles.navRight}>
                <div className={styles.headerPhone}>+7 (911) 910-40-12 | СПб</div>
                <Link href="/contacts" className="primary-button primary-button--filled">
                    Отправить файл
                </Link>
            </div>
        </nav>
    );
};

export default Navbar;
